import type { TroubleCodeGuide } from "./trouble-code-data";

const hondaInfo={label:"Honda ServiceExpress technical information",url:"https://techinfo.honda.com/",note:"Honda's service publications, wiring information and model/year repair procedures"};
const hondaManuals={label:"Honda Accord authorized manuals",url:"https://techinfo.honda.com/rjanisis/pubs/OM/AH/A30A2525IOM/enu/details/info-AuthorizedManuals.html",note:"Honda directs owners and technicians to ServiceExpress for electronic service publications"};
const vtecSwitch={label:"Honda Service Bulletin 13-021 — P2646/P2651 or P2647/P2652",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10052884-2696.pdf",note:"All 2003–2012 Accord four-cylinder models; intermittent rocker-arm oil-pressure switch failure, followed by normal troubleshooting if the code returns"};
const catalyst2010={label:"Honda Service Bulletin 14-002 — 2010 Accord V6 P0420/P0430",url:"https://static.nhtsa.gov/odi/tsbs/2014/MC-10142653-9999.pdf",note:"Narrow 2010 Accord V6 VIN ranges only; an A/F Sensor 1 cap may damage the affected warm-up catalyst"};
const hybridCatalyst={label:"Honda Service Bulletin 18-022 notice — 2006–2007 Accord Hybrid catalyst",url:"https://static.nhtsa.gov/odi/tsbs/2018/MC-10143223-9999.pdf",note:"Historical 2006–2007 Accord Hybrid campaign/warranty notice with geographic and time limitations; verify VIN and current status"};
const evap2012={label:"Honda Service Bulletin 14-010 — Accord P0455/P0456 software",url:"https://static.nhtsa.gov/odi/tsbs/2014/MC-10129552-9999.pdf",note:"All 2012 Accords and narrowly listed early-production 2013 Accord VINs; check exact applicability and current program status"};
const misfireV6={label:"Honda Service Bulletin 10-033 — Accord V6 P0300–P0304",url:"https://static.nhtsa.gov/odi/tsbs/2014/MC-10129514-9999.pdf",note:"Superseded by 13-078 for covered 2008–2012 Accord V6 P0301–P0304 warranty-extension cases; confirm VIN, current status and diagnosis"};
const p1457Old={label:"Honda Service Bulletin 03-001 — P1457 bypass solenoid corrosion",url:"https://workshop-manuals.com/honda/accord_ex_coupe/l4-2254cc_2.3l_sohc_%28vtec%29_mfi/powertrain_management/relays_and_modules_powertrain_management/relays_and_modules_computers_and_control_systems/engine_control_module/component_information/technical_service_bulletins/all_technical_service_bulletins_for_engine_control_module/03-001/jan/03/emissions/engine_controls_mil_on/dtc_p1457_%28evap%29/",note:"1998–2002 Accord among listed models; salt-water corrosion can affect the EVAP bypass solenoid and, rarely, the ECM/PCM"};
const p1457Early={label:"Honda Service Bulletin 01-011 — 1998–1999 Accord P1457",url:"https://workshop-manuals.com/honda/accord_lx_coupe/l4-2254cc_2.3l_sohc_%28vtec%29_mfi/powertrain_management/emission_control_systems/evaporative_emissions_system/evaporative_shut_valve/component_information/technical_service_bulletins/all_technical_service_bulletins_for_evaporative_shut_valve/01-011/mar/01/mil_on_dtc_p1457_set/",note:"Specific 1998–1999 Accord diagnostic/calibration and canister vent-shut-valve branches; verify VIN and freeze data"};

const vehicle={name:"Honda Accord",kicker:"HONDA ACCORD · ENGINE, VTEC AND EMISSIONS DIAGNOSTICS",breadcrumb:"Honda Accord",about:"Honda Accord engine and emissions diagnostics",yearsIntro:"Accord diagnostics span older F-series four-cylinders and J-series V6 engines, K-series four-cylinders with rocker-arm oil-pressure monitoring, Earth Dreams direct-injection engines, 1.5L and 2.0L turbo powertrains, and multiple hybrid generations. Cylinder/bank layout, VTEC/VTC oil control, EVAP strategy, catalyst monitoring and fuel delivery differ. Confirm model year, VIN, engine, transmission, hybrid status, emissions label and current Honda bulletin/campaign eligibility before choosing a test or part."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`honda/accord/${x.slug}`,vehicle});

export const troubleCodeAccord:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Honda Accord: Catalyst Diagnosis by Engine and VIN",description:"Diagnose Accord P0420 by testing misfire, fuel control, exhaust leaks and sensor response, with exact 2010 V6 and 2006–2007 Hybrid bulletin limits.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"A steady P0420 with normal power usually permits a short diagnostic trip. Avoid prolonged high load until active misfire and restriction are ruled out. Stop for a flashing MIL, raw-fuel odor, severe roughness, catalyst rattle or major power loss because unburned fuel or broken substrate can overheat or block the exhaust.",quickAnswer:"P0420 means the PCM judged Bank 1 catalyst oxygen-storage performance below threshold; it does not identify what degraded the catalyst. Save freeze data and readiness, repair misfire or mixture faults, check oil/coolant consumption and exhaust leaks, then compare upstream A/F and downstream O2 behavior under the correct Honda procedure. Two Accord-specific exceptions require VIN verification. Bulletin 14-002 covers narrow 2010 V6 VIN ranges where an A/F Sensor 1 cap may fall off and damage a warm-up catalyst. A separate historical notice covers certain 2006–2007 Accord Hybrids. Neither branch applies to ordinary four-cylinder, turbo or other-year Accords.",symptoms:[{key:"normal",label:"MIL on, engine feels normal",response:"Preserve monitor evidence and complete prerequisite tests before parts."},{key:"flash",label:"MIL flashes during acceleration",response:"Release load and stop sustained driving; repair the active misfire first."},{key:"rattle",label:"Rattle or loss of high-rpm power",response:"Inspect shields and test for broken/restricted catalyst substrate."},{key:"codes",label:"P2243/P2247 also stored on a 2010 V6",response:"Check exact VIN against bulletin 14-002 before disturbing sensors or catalysts."}],causes:[{cause:"Bank 1 catalyst deterioration or physical damage",evidence:"Prerequisites pass and Honda catalyst monitor test fails",firstTest:"Engine-specific catalyst evaluation"},{cause:"Misfire or rich operation overheated catalyst",evidence:"P030x history, flashing lamp, negative trims or deposits",firstTest:"Correct ignition/fuel cause first"},{cause:"Oil/coolant contamination",evidence:"Consumption, smoke, coolant loss or deposits",firstTest:"Mechanical/cooling diagnosis"},{cause:"Exhaust leak near monitored catalyst/sensors",evidence:"Cold tick, soot or leak-test evidence",firstTest:"Cold inspection and safe leak test"},{cause:"A/F or downstream O2 sensor/circuit problem",evidence:"Controlled response or electrical test fails",firstTest:"Graph sensors and test circuit"}],freezeFrame:["RPM, load, speed and coolant temperature","Misfire and fuel-trim history","A/F Sensor 1 and O2 Sensor 2 data","Oil/coolant consumption","Exhaust leak, rattle and restriction evidence","VIN, engine, calibration and emissions label"],steps:[{title:"Preserve all emissions evidence",detail:"Save confirmed, pending and permanent codes plus readiness before clearing."},{title:"Identify engine, bank and catalyst",detail:"Four-cylinder and V6/hybrid exhaust layouts use different bank and converter arrangements."},{title:"Resolve catalyst killers",detail:"Diagnose misfire, rich/lean control, oil consumption and coolant entry first."},{title:"Inspect the exhaust cold",detail:"Check flex sections, flanges, sensor bungs and shields without burn risk."},{title:"Apply VIN-specific Honda branches",detail:"Use 14-002 or the hybrid notice only when every applicability detail matches."},{title:"Complete the monitor",detail:"After repair, follow the Honda drive/monitor procedure and confirm no pending P0420."}],dontReplace:"Do not replace the downstream O2 sensor or converter from one code. Bulletin 14-002 requires the listed 2010 V6 VIN range and its physical failure condition. The 2006–2007 Hybrid notice was a time/geography-limited historical program; verify current VIN status rather than promising coverage.",yearNotes:["2010 V6: bulletin 14-002 lists narrow VIN ranges and possible P2243/P2247 companion codes from A/F Sensor 1 cap damage.","2006–2007 Accord Hybrid: bulletin 18-022 documentation describes a historical catalyst/software warranty action with exclusions and deadlines.","A four-cylinder has one bank; J-series V6 engines have two and require correct Bank 1 identification.","Turbocharged 1.5L/2.0L engines add boost, direct-injection and oil-dilution history to upstream diagnosis."],faqs:[{question:"Does P0420 prove the catalyst is bad?",answer:"No. Engine, exhaust and sensor prerequisites must be tested first."},{question:"Can I drive with P0420?",answer:"Usually briefly with a steady lamp and normal operation; stop for flashing, strong odor, rattle or power loss."},{question:"Will an oxygen sensor fix it?",answer:"Only if response and circuit testing proves that sensor or wiring faulty."},{question:"Does bulletin 14-002 cover every 2010 Accord?",answer:"No. It specifies V6 body/transmission configurations and narrow VIN ranges."},{question:"Is the old Hybrid extension still active?",answer:"Do not assume so; verify VIN and current campaign/warranty status with Honda."},{question:"Can oil use cause P0420?",answer:"Yes. Oil ash can contaminate catalyst material, so repair the consumption source."},{question:"Why did P0420 return after replacement?",answer:"An upstream fault, exhaust leak, incorrect part or sensor/circuit problem may remain."},{question:"What confirms repair?",answer:"Healthy fuel/misfire control and a completed catalyst monitor without pending P0420."}],deepDive:[{heading:"The 2010 V6 bulletin describes physical sensor damage",paragraphs:["Honda states that one or both A/F Sensor 1 caps may fall off and bore a hole through the affected warm-up catalyst. This is not generic sensor aging.","Verify the Accord's VIN against the published range and follow the retrieval/repair procedure. A shared model year without the matching V6/VIN is insufficient."]},{heading:"A catalyst can be the victim",paragraphs:["Repeated misfire, excessive fuel, oil burning or coolant entry can damage a replacement rapidly. Review historical codes and fluid consumption even if the engine is smooth today.","A flashing-MIL event under load is especially important. Do not erase it from the story just because P0420 is now the only confirmed code."]},{heading:"Hybrid and conventional monitor conditions differ",paragraphs:["The gasoline engine in a hybrid may stop while the vehicle remains operational, changing catalyst temperature and monitor opportunities.","Use Honda's hybrid-specific service mode and safety information. A generic steady-speed drive cycle may not produce a valid result."]}],sources:[catalyst2010,hybridCatalyst,hondaInfo,hondaManuals]}),

article({slug:"p0171",code:"P0171",title:"P0171 Code Honda Accord: Lean Fuel-Trim Diagnosis",description:"Diagnose Accord P0171 with idle-versus-load trims, intake smoke testing, MAF/MAP plausibility and measured fuel pressure across four-cylinder, V6 and turbo engines.",definition:"Fuel System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid hard acceleration and long trips when the Accord hesitates, stalls or has strongly positive fuel correction. Stop for a flashing MIL, detonation, severe power loss or fuel-pressure warnings. A smooth-running vehicle with a steady lamp can generally make a short controlled diagnostic trip.",quickAnswer:"P0171 means the PCM has added fuel beyond its correction limit for Bank 1; it does not name the upstream A/F sensor. Compare short- and long-term correction at hot idle, raised rpm and controlled load. Correction highest at idle suggests a vacuum/PCV/brake-booster or purge leak. Lean under load shifts attention toward fuel pressure/volume, MAF/MAP plausibility or injector delivery. On a V6, compare banks; a large split localizes intake, exhaust or injector causes. On turbo Accords, pressure leaks and high-/low-side fuel data matter. Honda has issued model-specific communications in other contexts, but no one bulletin supports a universal Accord P0171 part replacement.",symptoms:[{key:"idle",label:"Rough mainly at idle",response:"Compare correction at 2,500 rpm and smoke-test intake, PCV and brake-booster paths."},{key:"load",label:"Hesitation under load",response:"Graph commanded/actual fuel pressure and airflow/boost; stop if pressure falls."},{key:"v6",label:"P0171 without P0174 on a V6",response:"Use bank comparison to inspect Bank 1 intake sealing, exhaust and injector contribution."},{key:"fill",label:"Hard start after refueling",response:"Test purge valve sealing; excessive vapor can distort mixture control."}],causes:[{cause:"Unmetered intake/PCV/brake-booster air",evidence:"Positive correction strongest at idle and improves with rpm",firstTest:"Regulated smoke test"},{cause:"MAF/MAP under-reporting or intake restriction",evidence:"Air/load data implausible and both banks affected",firstTest:"Inspect intake and compare load sensors"},{cause:"Low fuel pressure or injector delivery",evidence:"Correction worsens under load or start pressure is slow",firstTest:"Engine-specific low/high-side pressure test"},{cause:"Bank 1 exhaust leak or injector imbalance",evidence:"V6 bank split, cold tick or contribution difference",firstTest:"Leak and injector balance tests"},{cause:"A/F sensor or circuit bias",evidence:"Circuit/controlled response fails after mixture causes excluded",firstTest:"Honda signal and circuit procedure"}],freezeFrame:["Short- and long-term fuel correction for all banks","RPM, load, coolant temperature and speed","MAF/MAP and throttle data","Low/high fuel pressure where supported","A/F sensor and misfire data","Recent intake, injector, turbo or purge work"],steps:[{title:"Save correction before reset",detail:"Learned data and freeze frame reveal whether the fault is idle-, load- or bank-specific."},{title:"Confirm engine architecture",detail:"Speed-density, MAF, V6 bank and turbo direct-injection tests differ by generation."},{title:"Compare idle and raised rpm",detail:"The direction and size of correction change guide the next test."},{title:"Smoke-test the entire metered path",detail:"Include PCV, brake booster, manifold seals and charge pipes where applicable."},{title:"Measure fuel delivery during demand",detail:"Idle pressure alone can miss a weak pump or high-side control issue."},{title:"Verify both correction and monitor",detail:"Repeat the original load safely and confirm no pending P0171."}],dontReplace:"Do not replace the upstream A/F sensor because the code says lean. A correctly working sensor is often reporting extra air or insufficient fuel. Avoid spraying flammable cleaner around a running engine; use smoke and data instead.",yearNotes:["Older F-series and K-series four-cylinders do not share every intake, PCV or sensor arrangement.","J-series V6 bank comparison is valuable: equal lean correction suggests a shared cause; one-bank correction suggests localization.","2018+ turbo engines require charge-air integrity and both low- and high-pressure fuel-system analysis.","Hybrid engine operation and sensor strategy require the specific model-year Honda procedure."],faqs:[{question:"Does P0171 mean a bad oxygen sensor?",answer:"No. It often means the sensor is correctly reporting a lean mixture."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially when correction is most positive at idle."},{question:"What if a V6 also has P0174?",answer:"Both banks lean moves shared air metering, intake and fuel delivery higher on the list."},{question:"Can a purge valve cause P0171?",answer:"A leak can disturb mixture, although purge vapor often creates a richer post-refuel pattern; test rather than assume."},{question:"Can I drive?",answer:"Limit driving if it hesitates or stalls; stop for flashing MIL or serious power loss."},{question:"Will cleaning a MAF fix it?",answer:"Only if the engine uses a MAF and data/inspection supports contamination; preserve evidence first."},{question:"Why test fuel pressure under load?",answer:"A marginal supply may meet idle demand but fall behind during acceleration."},{question:"What confirms repair?",answer:"Controlled correction at idle and load with no pending P0171."}],deepDive:[{heading:"Honda generations do not use one airflow strategy",paragraphs:["Some Accord diagnostics lean heavily on MAP and calculated load, while other engines provide MAF and direct-injection pressure data. Identify the system before copying a grams-per-second rule.","Use agreement among airflow, pressure, throttle and correction—not a single PID—to decide whether the measured load is believable."]},{heading:"A V6 supplies a control bank",paragraphs:["When only Bank 1 correction rises, inspect that bank's manifold sealing, exhaust ahead of the A/F sensor and injector contribution.","When both banks rise similarly, a single shared intake leak or fuel-supply fault becomes more plausible than two sensors failing together."]},{heading:"Turbo lean faults need pressure context",paragraphs:["A charge-air leak may appear mainly under boost, while an intake vacuum leak dominates idle. Graph load and boost/pressure with correction.","Direct injection adds a high-pressure side. Use specified safety procedures; never loosen a pressurized fuel line to see whether fuel is present."]}],sources:[hondaInfo,hondaManuals]}),

article({slug:"p0300",code:"P0300",title:"P0300 Code Honda Accord: Random Misfire Diagnosis",description:"Diagnose Accord P0300 using cylinder counters, fuel correction, ignition, injectors and compression, with exact V6 bulletin limits and catalyst safety.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing MIL means the misfire is active enough to threaten the catalysts. Reduce load and stop as soon as safe; do not keep accelerating to test it. A steady lamp with smooth operation may allow a short diagnostic move, but stop for severe shaking, raw-fuel odor, mechanical noise, overheating or low oil pressure.",quickAnswer:"P0300 records crankshaft-speed disturbances across multiple cylinders or without one cylinder consistently dominating. It does not mean replace every plug or coil. Save P0301–P0306 companions and cylinder counts at the same coolant temperature, rpm and load as freeze data. One cylinder needs targeted ignition, injector and compression tests; one V6 bank suggests bank-specific fueling, air or mechanical causes; both banks point toward shared fuel, air, timing or control. Honda bulletin 10-033 and its superseding warranty information concern defined 2008–2012 V6 Accord P0301–P0304 cases. They do not cover four-cylinder misfire or automatically approve piston-ring work without the required diagnosis and VIN eligibility.",symptoms:[{key:"flash",label:"MIL flashes and engine shakes",response:"Stop sustained driving to protect the warm-up and underfloor catalysts."},{key:"cold",label:"Misfire mainly after cold soak",response:"Save cylinder counts immediately; test injector leakage, ignition and sealing while cold."},{key:"oil",label:"Oil use plus V6 P0301–P0304",response:"Check exact 2008–2012 V6 bulletin/warranty applicability and follow Honda diagnosis."},{key:"load",label:"Breaks up under boost or acceleration",response:"Test ignition reserve, plug condition and fuel pressures under controlled load."}],causes:[{cause:"Worn/fouled plug, weak coil or boot tracking",evidence:"One cylinder leads and controlled swap follows",firstTest:"Inspect labeled plugs and targeted coil swap"},{cause:"Injector leakage, restriction or fuel-pressure fault",evidence:"Cold/load pattern, pressure anomaly or contribution result",firstTest:"Pressure and injector balance/leak test"},{cause:"Oil-fouled plug/ring issue in exact V6 population",evidence:"Oil use, fouled cylinder and matched VIN/bulletin diagnosis",firstTest:"Honda 13-078 eligibility and inspection"},{cause:"Intake, PCV, purge or EGR distribution fault",evidence:"Fuel correction pattern and multiple cylinders affected",firstTest:"Smoke/flow and bank analysis"},{cause:"Compression, valve clearance or cam timing problem",evidence:"Persistent cylinder/bank pattern or low relative compression",firstTest:"Relative compression then leak-down/timing"}],freezeFrame:["Cylinder-specific misfire counters","RPM, load, coolant temperature and speed","Fuel correction for all banks","Low/high fuel pressure where applicable","Oil consumption and plug condition by cylinder","Companion ignition, injector, VTC/VTEC and catalyst codes"],steps:[{title:"Preserve the cylinder pattern",detail:"Do not clear codes or swap all coils before recording which cylinders lead."},{title:"Classify one cylinder, one bank or shared",detail:"Distribution turns P0300 into a focused diagnostic path."},{title:"Inspect plugs in cylinder order",detail:"Deposits, gap and oil/coolant evidence are lost if plugs are mixed."},{title:"Separate ignition from fuel",detail:"Use targeted swaps, injector data and pressure tests rather than replacing sets."},{title:"Prove mechanical sealing",detail:"A fault that stays with a cylinder after ignition/fuel tests needs compression and leak-down evidence."},{title:"Apply V6 coverage only when exact",detail:"Verify VIN, year, symptoms and current Honda program terms."},{title:"Repeat the original condition",detail:"Confirm counters remain stable cold and under safe load with no pending code."}],dontReplace:"Do not install four or six coils from P0300. Do not promise the V6 ring-related warranty repair from a generic code match: Honda's coverage is limited by model year, engine, VIN/program rules and diagnostic findings.",yearNotes:["2008–2012 Accord V6: Honda issued specific P0301–P0304 warranty guidance that superseded bulletin 10-033.","Four-cylinder K-series and later direct-injected/turbo engines are not included in that V6 remedy.","Cylinder numbering and bank layout must be taken from the exact engine, especially before interpreting P0301–P0306.","Hybrid misfire diagnosis must account for commanded engine-off periods and high-voltage safety."],faqs:[{question:"Can I drive with P0300?",answer:"Not with a flashing MIL, severe shaking or raw-fuel odor; those conditions can damage catalysts quickly."},{question:"Will plugs fix it?",answer:"Only if inspection shows worn, fouled, damaged or incorrect plugs."},{question:"Why is there no cylinder code?",answer:"Misfire may be distributed or inconsistent; enhanced counters can still show a leader."},{question:"Does every V6 qualify for the Honda warranty extension?",answer:"No. Eligibility and remedy depend on the exact VIN, year, current program terms and diagnosis."},{question:"Can oil consumption cause misfire?",answer:"Yes. Oil-fouled plugs can misfire, but the source and affected cylinder must be proven."},{question:"Can a bad injector cause cold misfire?",answer:"Yes. Leakage or poor delivery may be most visible immediately after a soak."},{question:"Should I clear it before diagnosis?",answer:"No. Save freeze data, counters and readiness first."},{question:"What confirms repair?",answer:"Stable counters through the original cold/load condition and no pending P0300."}],deepDive:[{heading:"P0300 is less useful than the cylinder distribution",paragraphs:["Watch enhanced Honda misfire data during cold start, idle and a safe load event. A leading cylinder supports a local test even before a mature P0301 code appears.","Multiple adjacent cylinders or one bank should shift attention toward shared intake, fuel or mechanical systems before a bag of coils."]},{heading:"The V6 bulletin is not a universal misfire shortcut",paragraphs:["Honda's earlier 10-033 document was replaced by separate warranty-extension material for specified 2008–2012 Accord V6 P0301–P0304 cases.","Confirm oil use, plug fouling and the required diagnostic result. A four-cylinder P0300 or an unmatched V6 returns to normal troubleshooting."]},{heading:"Protect the catalyst while testing",paragraphs:["Repeatedly loading an active misfire can send raw fuel into the warm-up catalyst. Use brief controlled tests and stop when counts rise sharply.","After repair, check whether P0420/P0430 became pending and verify the catalyst monitor later. Fixing the misfire does not guarantee the catalyst escaped damage."]}],sources:[misfireV6,hondaInfo,hondaManuals]}),

article({slug:"p2646",code:"P2646",title:"P2646 Code Honda Accord: Rocker-Arm Oil Pressure Switch Low",description:"Diagnose Accord P2646 by checking oil level/pressure, VTEC spool-valve flow, switch voltage and wiring, with exact Honda bulletin 13-021 coverage.",definition:"Rocker Arm Oil Pressure Switch Circuit Low Voltage (VTEC System)",severity:"Diagnose promptly",driveAdvice:"Check engine-oil level before driving. Stop for an oil-pressure warning, knocking, severe valvetrain noise or oil below the safe range. If oil is correct and the engine is quiet, avoid high rpm and hard acceleration because VTEC engagement may be inhibited and the PCM may impose a rev limit until diagnosis.",quickAnswer:"P2646 means the PCM saw the rocker-arm/VTEC oil-pressure switch circuit remain low when the commanded VTEC state required a different response. That can be an intermittent switch, low/dirty/wrong oil, inadequate engine oil pressure, a restricted spool-valve screen or oil passage, a stuck oil-control solenoid, connector damage or wiring to the PCM. Honda bulletin 13-021 explicitly covers all 2003–2012 four-cylinder Accords and identifies intermittent rocker-arm oil-pressure switch failure; it instructs replacement of the switch and O-ring, then normal code troubleshooting if the DTC returns. Check actual lubrication and circuit evidence before treating the bulletin as permission to replace an entire spool-valve assembly.",symptoms:[{key:"limit",label:"Engine will not rev normally",response:"Avoid forcing through the limit; the PCM may be protecting against unverified VTEC oil pressure."},{key:"oil",label:"Oil low or oil-pressure lamp on",response:"Stop and correct/diagnose lubrication before operating the VTEC system."},{key:"intermittent",label:"Code disappears after restart",response:"Preserve freeze data; 13-021 notes the switch failure can be intermittent."},{key:"return",label:"Code returns after switch replacement",response:"Follow Honda circuit, spool-valve, oil-flow and mechanical-pressure troubleshooting."}],causes:[{cause:"Intermittent rocker-arm oil-pressure switch",evidence:"2003–2012 L4 match and switch/circuit test supports it",firstTest:"Apply bulletin 13-021 exactly"},{cause:"Low, wrong, degraded or aerated engine oil",evidence:"Level/condition/grade wrong or symptom on turns",firstTest:"Verify oil correctly and inspect for leaks/consumption"},{cause:"Restricted spool-valve screen or oil passage",evidence:"Debris/sludge and inadequate VTEC circuit pressure",firstTest:"Inspect using engine-specific Honda procedure"},{cause:"VTEC oil-control solenoid or circuit fault",evidence:"Command/current or hydraulic response fails",firstTest:"HDS command and loaded circuit test"},{cause:"Low mechanical engine oil pressure",evidence:"Warning/noise or pressure below specification",firstTest:"Mechanical pressure test before further running"}],freezeFrame:["Engine rpm, load, vehicle speed and oil temperature context","Engine oil level, grade and service history","VTEC command and pressure-switch state","Battery/system voltage","Companion oil-control, VTC and pressure codes","Connector contamination and harness movement sensitivity"],steps:[{title:"Verify engine oil safely",detail:"Park level, wait as specified and record level/condition/grade before adding or draining."},{title:"Confirm exact engine and bulletin coverage",detail:"13-021 covers 2003–2012 Accord four-cylinder, not every Accord engine/year."},{title:"Inspect connector and switch circuit",detail:"Check oil intrusion, terminal fit, reference/pull-up behavior and continuity under movement."},{title:"Command the VTEC system",detail:"Use HDS data to compare oil-control command with switch response under safe conditions."},{title:"Test oil supply when code returns",detail:"Inspect screen/passages and measure pressure as Honda specifies."},{title:"Verify across the enabling rpm/load",detail:"Confirm normal switch transition and no pending P2646 without forcing an unsafe test."}],dontReplace:"Do not replace the whole VTEC spool-valve assembly because P2646 is common. Bulletin 13-021 names the rocker-arm oil-pressure switch for covered vehicles, but a returning code requires normal diagnosis. Never mask low mechanical oil pressure with an electrical part.",yearNotes:["2003–2012 Accord four-cylinder: all are listed in Honda bulletin 13-021.","The bulletin's repair uses a new switch and O-ring and specifies 22 N·m (16 lb-ft) in its procedure; verify current service information before work.","V6 and newer turbo/hybrid powertrains are not automatically included in that bulletin despite similar code wording.","Oil viscosity and service interval must follow the exact engine/owner documentation."],faqs:[{question:"Is P2646 always the VTEC switch?",answer:"No. The switch is covered on specified cars, but oil supply, solenoid, screen, wiring and mechanical pressure remain possible."},{question:"Can low oil cause it?",answer:"Yes. The system depends on engine oil pressure and correct oil level."},{question:"Can I drive?",answer:"Avoid high rpm; stop immediately for an oil-pressure warning, knocking or very low oil."},{question:"Why does it limit rpm?",answer:"The PCM may inhibit VTEC or limit operation when it cannot verify rocker-arm oil pressure."},{question:"Does 13-021 cover a V6?",answer:"No. Its Accord applicability is 2003–2012 four-cylinder."},{question:"Should I clean the screen?",answer:"Inspect it using the correct procedure; cleaning alone does not repair a failed switch, solenoid, wiring or low pressure."},{question:"Why did it return after a new switch?",answer:"Circuit damage, poor oil supply, a stuck control solenoid or mechanical pressure loss may remain."},{question:"What confirms repair?",answer:"Correct command-to-switch transition under the enabling condition and no pending P2646."}],deepDive:[{heading:"The switch reports hydraulic success",paragraphs:["The PCM commands the oil-control solenoid and expects the pressure switch to reflect hydraulic state. A low circuit result can therefore be electrical or a truthful report of missing pressure.","Test the command, circuit state and oil supply together. One resistance reading with the engine off cannot prove the full system."]},{heading:"Bulletin 13-021 has a clear fallback",paragraphs:["Honda acknowledges intermittent switch failure on the covered population and gives a switch/O-ring replacement procedure.","It also says that if the DTC returns, use the normal troubleshooting procedure. That prevents repeat switch replacement when the cause is oil flow, solenoid control or wiring."]},{heading:"Oil condition is diagnostic evidence",paragraphs:["Record level, viscosity, filter and change history. Sludge/debris may restrict a small screen or passage, while low pressure can reflect a broader engine problem.","Do not substitute thicker oil or overfill to make the code disappear. Correct the specification and diagnose pressure mechanically if symptoms require it."]}],sources:[vtecSwitch,hondaInfo,hondaManuals]}),

article({slug:"p2647",code:"P2647",title:"P2647 Code Honda Accord: Rocker-Arm Oil Pressure Switch High",description:"Diagnose Accord P2647 high switch voltage by comparing VTEC command, oil-pressure switch state, wiring and oil control, using Honda 13-021 precisely.",definition:"Rocker Arm Oil Pressure Switch Circuit High Voltage (VTEC System)",severity:"Diagnose promptly",driveAdvice:"Verify oil level immediately. Stop if the oil-pressure warning appears, oil is dangerously low or the valvetrain knocks. With correct oil and no mechanical noise, keep rpm/load modest; the PCM may limit performance because the switch indicates pressure when the commanded system state says it should not.",quickAnswer:"P2647 is the high-state counterpart to P2646: the PCM sees the rocker-arm oil-pressure switch circuit high when VTEC command logic expects the other state. Possible causes include an intermittent switch stuck in the wrong state, open/shorted wiring depending on circuit design, connector oil/water intrusion, a spool valve held hydraulically on, restricted drain/oil passages, wrong oil or a PCM-side circuit fault. Honda bulletin 13-021 covers P2647/P2652 as well as low-voltage codes on every 2003–2012 four-cylinder Accord and identifies intermittent switch failure. Replace only through that exact branch; if P2647 returns, proceed with full Honda circuit and hydraulic diagnosis.",symptoms:[{key:"light",label:"MIL intermittent with normal driving",response:"Save occurrence/freeze data; Honda notes the switch fault may not duplicate after clearing."},{key:"limit",label:"Reduced rpm or hesitation near VTEC transition",response:"Do not repeatedly force engagement; compare command and switch data."},{key:"oil",label:"Wrong level or recent oil service",response:"Correct level/grade and inspect filter/leaks before electrical assumptions."},{key:"after",label:"Code after spool-valve or engine work",response:"Inspect connector identity, pin fit, gasket/screen orientation and harness routing."}],causes:[{cause:"Intermittent rocker-arm oil-pressure switch",evidence:"Covered 2003–2012 L4 plus matching switch/circuit result",firstTest:"Honda 13-021 branch"},{cause:"Open/short or poor terminal in switch circuit",evidence:"Signal high regardless of switch state or harness movement",firstTest:"Loaded circuit and terminal test"},{cause:"Oil-control solenoid/spool valve held on",evidence:"Hydraulic pressure/state remains when command is off",firstTest:"HDS command and oil-control test"},{cause:"Restricted screen, return or oil passage",evidence:"Contamination and abnormal state transition",firstTest:"Engine-specific passage/screen inspection"},{cause:"Incorrect oil level/viscosity or pressure behavior",evidence:"Service history and pressure outside specification",firstTest:"Correct oil verification and pressure test"}],freezeFrame:["VTEC/rocker-arm oil-control command","Oil-pressure switch state","RPM, load, speed and coolant temperature","System voltage","Oil level, viscosity and service history","Companion P2646/P2651/P2652, VTC and circuit codes"],steps:[{title:"Treat high and low codes differently",detail:"P2647 means the observed electrical state is high; do not copy a P2646 wiring conclusion."},{title:"Verify oil and engine condition",detail:"Check correct level/grade and stop for pressure warning or mechanical noise."},{title:"Check 13-021 applicability",detail:"All 2003–2012 Accord four-cylinder models are listed; other engines/years require their own procedure."},{title:"Test the switch circuit in both states",detail:"Use HDS commands and voltage/continuity tests with the circuit connected as specified."},{title:"Prove hydraulic release",detail:"If the circuit works, inspect whether the spool valve and oil passages actually return pressure."},{title:"Recreate without abuse",detail:"Verify the expected transition at safe rpm/load and no pending P2647."}],dontReplace:"Do not interpret P2647 as 'replace VTEC solenoid.' Honda's covered repair centers on an intermittent pressure switch, yet a code that returns after that repair demands wiring, solenoid and oil-flow testing. Parts sharing one housing are not automatically all failed.",yearNotes:["Honda 13-021 lists all 2003–2012 Accord four-cylinder models for P2647/P2652 and related low-state codes.","Circuit logic matters: an open circuit may display high depending on the PCM pull-up; use the exact diagram.","A V6 or later turbo Accord may use different hardware and is not covered simply because a scan tool displays P2647.","Any oil-pressure warning or valvetrain noise outranks the DTC and requires immediate lubrication diagnosis."],faqs:[{question:"What is the difference between P2646 and P2647?",answer:"They describe opposite monitored switch-circuit states relative to VTEC command: low versus high."},{question:"Is the VTEC solenoid always bad?",answer:"No. The pressure switch, circuit, oil supply and passages must be separated from solenoid control."},{question:"Does Honda 13-021 cover my 2009 four-cylinder?",answer:"Yes, 2003–2012 Accord four-cylinder models are listed, subject to current service/warranty rules."},{question:"Can wrong oil cause it?",answer:"Oil level, viscosity and condition affect hydraulic response and must be correct."},{question:"Can I drive?",answer:"Keep rpm low and stop for pressure warning, low oil or noise."},{question:"Why is the fault intermittent?",answer:"Switch contacts or connector/harness faults can change with temperature, vibration and oil exposure."},{question:"Should I replace the whole spool valve?",answer:"Not without evidence. Bulletin 13-021 specifies the pressure switch and O-ring for its branch."},{question:"What confirms repair?",answer:"The switch state follows VTEC command correctly and P2647 does not return."}],deepDive:[{heading:"High state does not necessarily mean high oil pressure",paragraphs:["The scan code describes circuit voltage interpreted by the PCM. A broken wire or terminal can imitate a switch reporting pressure, depending on circuit design.","Use the Honda wiring diagram and measure under load. A continuity beep alone may miss resistance or an intermittent open."]},{heading:"Hydraulic release is as important as engagement",paragraphs:["P2647 can arise when the system appears to remain pressurized after the command changes. Oil-control spool movement and return passages therefore matter.","Graph command and switch state through a safe transition. If electrical state is truthful, move to hydraulic tests instead of installing another switch."]},{heading:"A bulletin repair is not endless authorization",paragraphs:["13-021 recognizes intermittent switch failure and gives a defined replacement. It does not say every recurrence is another bad new switch.","When the code returns, Honda directs normal troubleshooting. Recheck terminals, control current, screen/passages and actual engine oil pressure."]}],sources:[vtecSwitch,hondaInfo,hondaManuals]}),

article({slug:"p1457",code:"P1457",title:"P1457 Code Honda Accord: Canister-Side EVAP Leak Diagnosis",description:"Diagnose older Accord P1457 canister-side EVAP leaks with valve commands, tank-pressure data and smoke isolation, including salt-corrosion bulletin limits.",definition:"EVAP Control System Leakage (Canister System)",severity:"Service soon",driveAdvice:"P1457 usually does not make the Accord unsafe to steer or brake, but gasoline vapor is flammable. Stop and park outdoors for strong fuel odor, liquid leakage, a damaged tank or refueling spit-back. Do not smoke, create sparks or pressurize the EVAP system with unregulated shop air.",quickAnswer:"On the older Honda strategy that uses P1456/P1457, P1457 localizes the failed leak test toward the canister side rather than the fuel-tank side. That still does not name one valve. Inspect rear vapor hoses, canister, vent-shut and bypass solenoids, two-way valve, tank-pressure sensing and wiring; command valves with Honda-capable data and isolate sections using regulated smoke. Accord-specific history matters: bulletin 03-001 covers 1998–2002 Accords where water/road-salt corrosion can damage the EVAP bypass solenoid and, rarely, the ECM/PCM. Bulletin 01-011 contains narrower 1998–1999 calibration/vent-shut-valve branches. Test the exact VIN and freeze data before replacing components.",symptoms:[{key:"salt",label:"Older Accord operated in road-salt region",response:"Inspect bypass/vent solenoid connectors and circuits for water/salt corrosion."},{key:"alone",label:"P1457 with no fuel odor",response:"Preserve tank-pressure freeze data and run canister-side isolation tests."},{key:"odor",label:"Strong vapor or wet fuel",response:"Stop, ventilate and inspect for liquid-fuel leakage before powered tests."},{key:"repeat",label:"Valve replaced but P1457 returned",response:"Test hose routing, internal leakage, pressure sensing and PCM circuit damage."}],causes:[{cause:"Corroded EVAP bypass solenoid",evidence:"1998–2002 match, salt/water evidence and failed valve/circuit test",firstTest:"Apply 03-001 diagnostic branch"},{cause:"Canister vent-shut valve failure",evidence:"Valve does not seal/flow under command",firstTest:"Bidirectional and vacuum test"},{cause:"Cracked/disconnected rear vapor hose or canister",evidence:"Visible damage or localized smoke",firstTest:"Regulated sectional smoke test"},{cause:"Two-way valve or internal system leak",evidence:"External system holds but pressure sequence fails",firstTest:"Honda internal-leak procedure"},{cause:"Tank-pressure sensor or ECM/PCM circuit issue",evidence:"Biased/fluctuating PID or corrosion-related circuit failure",firstTest:"Controlled pressure and electrical test"}],freezeFrame:["Fuel-tank pressure sensor voltage/value","Fuel level and ambient temperature","Purge, vent and bypass command states","P1456 or electrical companion codes","Salt/water exposure and corrosion evidence","Recent canister, tank or rear-body service"],steps:[{title:"Confirm this is the older two-part Honda strategy",detail:"Later Accord generations use different generic EVAP codes and hardware."},{title:"Preserve pressure and feedback data",detail:"Early Honda bulletin decisions depend on freeze-data state and sensor plausibility."},{title:"Inspect canister-side hardware",detail:"Check rear hoses, canister and solenoid connectors for cracks, water and salt."},{title:"Command each valve",detail:"A click does not prove sealing; verify flow/vacuum and electrical integrity."},{title:"Isolate with low-pressure smoke",detail:"Use approved EVAP pressure and follow Honda's valve sequence."},{title:"Verify the self-test",detail:"Complete enabling conditions and confirm no pending P1457."}],dontReplace:"Do not replace the charcoal canister or ECM from P1457 alone. Bulletin 03-001 requires testing the bypass solenoid and recognizes ECM/PCM damage only in rare severe-corrosion cases. Repair the water/corrosion path and prove circuit damage before module replacement.",yearNotes:["1998–2002 Accord: bulletin 03-001 includes bypass-solenoid corrosion, especially where road salt is used.","1998–1999 Accord: bulletin 01-011 separates PCM/calibration and vent-shut-valve branches using freeze data and vehicle conditions.","P1457 belongs to older Honda EVAP localization; newer Accords commonly use P0441/P0455/P0456 and different hardware.","A fuel cap is more directly associated with tank-side sealing; P1457 directs attention toward the canister side but still requires testing."],faqs:[{question:"Is P1457 a gas-cap code?",answer:"It localizes the older Honda leak test toward the canister side, so a cap is not the automatic answer."},{question:"Can I drive?",answer:"Usually briefly if there is no fuel odor or wetness; stop for any liquid leak."},{question:"Does road salt matter?",answer:"Yes. Honda documented salt-water corrosion of the bypass solenoid on listed older vehicles."},{question:"Can the PCM be damaged?",answer:"Bulletin 03-001 says severe internal solenoid corrosion can rarely damage it, but testing is required."},{question:"Can I smoke-test it?",answer:"Yes with approved regulated EVAP equipment and the correct valve sequence."},{question:"Why does it return after a valve?",answer:"Another valve, hose, internal leak, pressure sensor or circuit may remain faulty."},{question:"Is P1457 used on new Accords?",answer:"It is chiefly associated with older Honda EVAP strategy; verify the actual year/service code definition."},{question:"What confirms repair?",answer:"Correct pressure response and a completed EVAP self-test without pending P1457."}],deepDive:[{heading:"P1457 narrows the system, not the component",paragraphs:["Honda's older strategy separates tank-side and canister-side leak conclusions. P1457 moves testing rearward but cannot distinguish a hose from a valve or sensor.","Command valves and isolate sections before parts. Several components share the same pressure-test path."]},{heading:"Salt corrosion can become an electrical problem",paragraphs:["Bulletin 03-001 explains that water containing road salt can enter the bypass solenoid and corrode its winding. Inspect connector pins and resistance/command behavior.","Only severe internal shorting creates the rare ECM/PCM damage branch. Confirm driver/circuit function rather than replacing the module prophylactically."]},{heading:"Early freeze data controls the diagnostic branch",paragraphs:["Bulletin 01-011 uses primary oxygen-sensor feedback state and vehicle applicability to distinguish false-test/calibration from vent-valve behavior.","That historical logic should not be generalized to a 2001–2002 or later Accord. Retrieve the exact Honda procedure for the VIN."]}],sources:[p1457Old,p1457Early,hondaInfo]}),

article({slug:"p0135",code:"P0135",title:"P0135 Code Honda Accord: A/F Sensor Heater Circuit Diagnosis",description:"Diagnose Accord P0135 by identifying Bank 1 Sensor 1, testing heater power, control, resistance and current, and separating four-cylinder, V6 and turbo wiring.",definition:"Oxygen Sensor Heater Circuit Malfunction (Bank 1 Sensor 1)",severity:"Service soon",driveAdvice:"P0135 generally allows a short trip when the engine runs normally, but cold-start emissions and fuel control may be affected. Stop if it appears with a flashing misfire lamp, raw-fuel odor, smoke, a blown fuse that immediately opens again or melted exhaust wiring. Do not touch the sensor or harness until the exhaust is cold.",quickAnswer:"P0135 means the PCM did not see the expected electrical behavior from the Bank 1 Sensor 1 heater circuit. On many Accords, Sensor 1 is a wide-range A/F sensor, not a conventional narrowband oxygen sensor, so the correct part and test values must come from VIN-specific Honda information. Confirm the bank and connector, inspect for exhaust heat or rodent damage, then test fuse-fed power, PCM-controlled ground/driver, connector voltage drop, heater resistance and commanded current. A heater code is more electrical than a mixture code: intake leaks and fuel pressure do not repair an open heater element, while a new sensor cannot repair a missing feed or shorted harness.",symptoms:[{key:"cold",label:"MIL appears after cold start",response:"Save coolant temperature and time-to-fault; heater monitoring is most revealing cold."},{key:"fuse",label:"Heater fuse is blown",response:"Find a short before installing another fuse or sensor."},{key:"after",label:"Code followed exhaust/engine work",response:"Check connector identity, pin fit, clip routing and wires touching hot components."},{key:"codes",label:"Multiple sensor-heater codes",response:"Look for a shared fuse, relay, feed or ground rather than several simultaneous sensors."}],causes:[{cause:"Open heater element in Bank 1 Sensor 1",evidence:"Correct feeds/control but resistance/current fails specification",firstTest:"Cold heater resistance and commanded-current test"},{cause:"Missing fuse/relay power",evidence:"No battery feed at heater with command conditions met",firstTest:"Fuse, relay and loaded feed test"},{cause:"Open/short/high-resistance harness",evidence:"Voltage drop, rubbed/melted wire or wiggle failure",firstTest:"Loaded circuit and visual test"},{cause:"Poor connector pin fit, oil/water intrusion",evidence:"Corrosion, spread terminal or intermittent contact",firstTest:"Terminal tension and voltage-drop inspection"},{cause:"PCM heater-driver fault",evidence:"All external circuit/component tests pass but command absent",firstTest:"Verify driver at PCM after short protection checks"}],freezeFrame:["Coolant and intake-air temperature","Battery/system voltage","Time since engine start","Heater command/current where HDS exposes it","Other heater, fuse or charging codes","Recent exhaust, sensor or engine work"],steps:[{title:"Confirm Bank 1 Sensor 1",detail:"Use the engine diagram; do not confuse upstream A/F and downstream O2 connectors."},{title:"Inspect only when cold",detail:"Check heat shielding, clips, rodent damage and connector seating."},{title:"Test the power side under load",detail:"An unloaded test light/voltmeter can miss excessive resistance."},{title:"Measure the heater correctly",detail:"Use Honda temperature/specification limits and avoid probing signal pins incorrectly."},{title:"Verify PCM control and current",detail:"Confirm the driver can switch the known-good circuit without risking module damage."},{title:"Cold-start verification",detail:"Repeat from a comparable soak and confirm the heater monitor passes."}],dontReplace:"Do not order a generic 'O2 sensor' without confirming that the Accord uses an A/F sensor at Bank 1 Sensor 1, and do not replace it until heater power and control are proven. Universal splices near the exhaust can introduce resistance and repeat failures.",yearNotes:["Four-cylinder Accords have one bank; J-series V6 engines have two and require cylinder-based Bank 1 identification.","Upstream Honda A/F sensors use different signal behavior and part construction from downstream narrowband sensors.","Turbo and hybrid generations have different routing and control; match VIN, engine and connector.","Multiple heater codes strongly support a shared supply issue before individual sensor failure."],faqs:[{question:"Is Bank 1 Sensor 1 upstream?",answer:"Yes, Sensor 1 is ahead of the monitored catalyst; confirm the exact physical location by engine."},{question:"Is it an oxygen sensor or A/F sensor?",answer:"Many Accords use a wide-range A/F sensor upstream; order and test by VIN."},{question:"Can I drive?",answer:"Usually briefly if operation is normal, but stop for blown-fuse recurrence, melting or severe engine symptoms."},{question:"Can a fuse fix P0135?",answer:"A blown fuse indicates a cause; find a short or failed heater before replacement."},{question:"Can exhaust leaks cause P0135?",answer:"Leaks affect sensor readings, but P0135 specifically concerns heater-circuit behavior."},{question:"Can a weak battery set it?",answer:"Low system voltage can influence heater monitoring, so save voltage and charging codes."},{question:"Should I use a universal sensor?",answer:"Direct-fit VIN-correct parts avoid questionable splices and heater/signal mismatch."},{question:"What confirms repair?",answer:"Correct heater current/control and a passed cold-start monitor without pending P0135."}],deepDive:[{heading:"The sensor name is easy to get wrong",paragraphs:["Generic scanners call the component an O2 sensor, while Honda service information may describe the upstream device as an A/F sensor. The heater circuit still needs exact specifications.","Match engine, connector and part number. A downstream sensor that plugs in or a universal element may not have compatible heater characteristics."]},{heading:"Voltage present is not the same as a good circuit",paragraphs:["A corroded splice can show battery voltage with no load and collapse when the heater draws current. Measure voltage drop or current under commanded operation.","Test PCM-controlled circuits with the specified method. Grounding the wrong pin can damage a driver."]},{heading:"Use code grouping",paragraphs:["One heater code supports a local element, connector or branch fault. Several heater codes occurring together make a shared feed, fuse or relay more plausible.","Record which codes set first and whether the fuse opens immediately or only after vibration/heat. That timing localizes the short."]}],sources:[hondaInfo,hondaManuals]}),

article({slug:"p0455",code:"P0455",title:"P0455 Code Honda Accord: Large EVAP Leak Diagnosis",description:"Find Accord P0455 with cap, purge, vent, canister and low-pressure smoke tests, including Honda bulletin 14-010's exact 2012–2013 software limits.",definition:"EVAP System Large Leak Detected",severity:"Service soon",driveAdvice:"P0455 usually does not require an immediate stop if the Accord runs normally and there is no gasoline smell. Park outdoors and stop driving for strong vapor odor, visible fuel, tank damage or refueling spit-back. Keep ignition sources away and never pressure-test EVAP with unregulated shop air.",quickAnswer:"P0455 means the PCM could not pull or hold the expected vacuum/pressure during the EVAP self-test. A loose cap is possible, but an open purge or vent valve, disconnected hose, canister/tank leak or biased pressure sensor can look identical. Record the cap's found condition, fuel level and recent fuel-pump/body work. Command purge and vent, watch tank pressure and introduce approved low-pressure smoke. Honda bulletin 14-010 provides a software-update branch for all 2012 Accords and narrow early 2013 VIN ranges with P0455/P0456. It does not apply to a 2011, later-production 2013 or newer Accord simply because the code matches.",symptoms:[{key:"fill",label:"MIL followed refueling",response:"Record cap position and inspect its seal/filler surface before tightening."},{key:"year",label:"2012 or early-production 2013 Accord",response:"Check exact VIN and current calibration against bulletin 14-010."},{key:"start",label:"Hard start after filling",response:"Test purge valve closed-state sealing for vapor entering the intake."},{key:"odor",label:"Strong fuel odor or wetness",response:"Stop and inspect safely for a liquid leak before electrical testing."}],causes:[{cause:"Cap missing, loose, damaged or wrong",evidence:"Found condition or failed cap/filler sealing test",firstTest:"Inspect and pressure/vacuum test cap interface"},{cause:"Purge valve stuck open",evidence:"Intake vacuum reaches EVAP when purge is commanded off",firstTest:"Closed-state sealing test"},{cause:"Vent valve open or large hose disconnection",evidence:"System cannot seal and smoke exits",firstTest:"Bidirectional command and smoke test"},{cause:"Canister, tank or pump-module seal leak",evidence:"Localized smoke/pressure decay, often after service",firstTest:"Sectional low-pressure test"},{cause:"PCM software branch on exact 2012–2013 vehicles",evidence:"VIN/calibration matches 14-010 after physical checks",firstTest:"Honda bulletin applicability/calibration check"}],freezeFrame:["Fuel level and ambient/soak temperature","Fuel-tank pressure sensor data","Purge and vent command state","P0456/P0441 or circuit companion codes","Cap found condition and recent refueling","Fuel-pump, tank or rear-collision repair history"],steps:[{title:"Preserve cap and freeze evidence",detail:"Do not erase the refueling condition by automatically tightening first."},{title:"Check 14-010 by exact VIN",detail:"All 2012 are listed, but 2013 coverage stops at published early-production VINs."},{title:"Test purge and vent sealing",detail:"A solenoid click does not prove the valve closes."},{title:"Smoke-test at approved pressure",detail:"Inspect filler, hoses, canister and top-of-tank connections safely."},{title:"Validate tank-pressure response",detail:"A biased sensor can misreport a leak even when the system seals."},{title:"Complete the monitor after repair",detail:"Meet fuel-level/temperature/soak conditions and confirm no pending P0455."}],dontReplace:"Do not buy a cap and canister together. Each sealing point and valve can be tested. Do not perform a software update based on title alone; bulletin 14-010 has exact year/VIN applicability and requires approved Honda programming procedures.",yearNotes:["2012 Accord: all trims/VINs are listed in bulletin 14-010.","2013 Accord: only the published early-production four-cylinder and V6 VIN ranges are listed.","Older P1456/P1457 Honda EVAP strategy and later generic P0455 systems should not be mixed.","Hybrid and conventional models may package the tank/canister differently; use the VIN-correct schematic."],faqs:[{question:"Is P0455 always a loose gas cap?",answer:"No. Valves, hoses, canister, tank seals and pressure sensing can all create a large-leak result."},{question:"Does bulletin 14-010 cover every 2013 Accord?",answer:"No. It lists narrow early-production VIN ranges."},{question:"Can I drive?",answer:"Usually briefly if no odor or wet fuel exists; stop for evidence of liquid leakage."},{question:"Can a purge valve cause hard starting?",answer:"Yes. Vapor entering the intake while the valve should be closed can disturb a post-refuel start."},{question:"Can I use compressed air?",answer:"Not directly. Use approved, regulated low-pressure EVAP equipment."},{question:"Why did a new cap not help?",answer:"The leak or open valve may be elsewhere, or the filler sealing surface may be damaged."},{question:"Why will the monitor not run?",answer:"Fuel level, soak time, temperature and other DTCs control enable conditions."},{question:"What confirms repair?",answer:"Correct valve/pressure behavior and a completed EVAP monitor without pending P0455."}],deepDive:[{heading:"Honda's 14-010 branch is software, not a universal leak repair",paragraphs:["The bulletin covers defined 2012 and early-production 2013 vehicles. Confirm VIN and current PGM-FI calibration before programming.","A vehicle outside applicability still needs a physical leak/valve/sensor diagnosis. A software title cannot seal a disconnected hose."]},{heading:"The cap's found condition is perishable evidence",paragraphs:["If the lamp followed refueling, note whether the cap was loose, cross-threaded or obstructed. Tightening before recording removes a likely explanation.","Inspect the filler neck as well as the rubber seal. A good cap cannot seal against a damaged or contaminated surface."]},{heading:"A normal passage can imitate a giant hole",paragraphs:["The system must close purge/vent paths during portions of the test. A valve held open lets pressure escape without any cracked tank.","Command and verify actual sealing before replacing the canister. Electrical operation and mechanical sealing are separate questions."]}],sources:[evap2012,hondaInfo,hondaManuals]}),

article({slug:"p0128",code:"P0128",title:"P0128 Code Honda Accord: Thermostat and Warm-Up Diagnosis",description:"Diagnose Accord P0128 with a cold-soak sensor comparison and recorded warm-up curve; separate thermostat, coolant, ECT and fan-control faults.",definition:"Coolant Thermostat (Coolant Temperature Below Thermostat Regulating Temperature)",severity:"Service soon",driveAdvice:"P0128 normally reflects slow warm-up, but do not ignore the temperature gauge. Stop for overheating, steam, coolant loss, a warning message or heater output suddenly going cold. If coolant is full when checked safely, temperature remains stable and no leak exists, a short data-recording drive is generally reasonable.",quickAnswer:"P0128 means actual coolant temperature stayed below the PCM's expected regulating range after sufficient modeled warm-up. A thermostat stuck open is common, but diagnosis begins before start: after an overnight soak, ECT and intake-air temperature should be close to ambient. Graph ECT, load, speed, radiator-fan command and heater behavior through warm-up. A sensor biased cold, low coolant, trapped air, fan operation when not requested or a wrong thermostat can imitate the code. Search results frequently surface Subaru, Hyundai or Toyota P0128 bulletins; they do not authorize an Accord repair. Use Honda's exact engine/year service procedure.",symptoms:[{key:"heat",label:"Cabin heat takes too long",response:"Check coolant cold and graph warm-up; inspect for low level or air."},{key:"road",label:"Temperature falls at highway speed",response:"A thermostat unable to regulate becomes likely; confirm with scan data."},{key:"gauge",label:"Gauge appears normal",response:"Use the ECT PID because the dash gauge is intentionally damped."},{key:"hot",label:"Temperature climbs or coolant escapes",response:"Stop and diagnose overheating/leakage rather than completing a P0128 test."}],causes:[{cause:"Thermostat stuck open or incorrect",evidence:"Slow rise and ECT falls with road airflow",firstTest:"Record a full cold-start warm-up curve"},{cause:"ECT sensor/circuit biased cold",evidence:"Cold-soak ECT differs substantially from IAT/ambient",firstTest:"Sensor comparison and circuit test"},{cause:"Low coolant or trapped air",evidence:"Low cold level, recent service or unstable heat",firstTest:"Pressure/leak check and correct bleeding"},{cause:"Radiator fans operating without valid command",evidence:"Fans run cold with A/C off and no PCM request",firstTest:"Compare command, relay and actual operation"},{cause:"Another load/temperature input fault",evidence:"Companion DTC or implausible freeze data",firstTest:"Resolve prerequisite sensor faults"}],freezeFrame:["ECT, intake-air and known ambient temperature","Time since start, rpm, load and speed","Fan command and A/C request","Coolant level and recent service","Heater output and outside temperature","Companion temperature, voltage or airflow codes"],steps:[{title:"Begin with a true cold soak",detail:"Compare ECT and IAT before starting; a large mismatch cannot be caused by a thermostat."},{title:"Inspect cooling system cold",detail:"Check level and leaks without opening a hot pressurized system."},{title:"Graph the entire warm-up",detail:"Capture rise rate, regulation point and any highway temperature drop."},{title:"Check actual fan behavior",detail:"Unwanted fan operation can delay warm-up even with a good thermostat."},{title:"Verify the correct part and bleeding",detail:"Thermostat rating, seal/orientation and bleeding differ by Accord engine."},{title:"Repeat under comparable conditions",detail:"Confirm stable regulation and no pending P0128."}],dontReplace:"Do not replace the thermostat solely because it is common, and never apply another manufacturer's P0128 bulletin to an Accord. A biased ECT sensor can make a good cooling system appear cold, while low coolant can become an overheating hazard after the thermostat job.",yearNotes:["F-series, K-series, J-series, turbo and hybrid powertrains use different thermostat locations, specifications and bleeding methods.","Hybrid engine-off operation changes heat input and requires the hybrid-specific warm-up/verification method.","Cold weather and strong heater demand influence warm-up but do not erase repeatable failed monitor logic.","Use the Honda VIN/engine procedure rather than thermostat temperatures copied from another Accord generation."],faqs:[{question:"Is P0128 always a thermostat?",answer:"No. ECT bias, low coolant, trapped air and fan-control faults can mimic slow regulation."},{question:"Can I drive?",answer:"Usually briefly if temperature is stable and coolant is full; stop for overheating or leakage."},{question:"Why does the dash gauge look normal?",answer:"It is damped over a broad range; scan data gives diagnostic resolution."},{question:"Can cold weather set it?",answer:"It changes warm-up time, but the monitor has enabling logic; repeat failure still needs diagnosis."},{question:"Will fuel economy drop?",answer:"It can because prolonged warm-up affects enrichment and emissions operation."},{question:"Can I open the radiator hot?",answer:"No. Pressurized coolant can cause severe burns."},{question:"Does a Toyota or Subaru bulletin apply?",answer:"No. Use Honda Accord year/engine information only."},{question:"What confirms repair?",answer:"Plausible cold-soak values, normal rise/regulation and no pending P0128."}],deepDive:[{heading:"The cold-soak comparison is a no-parts test",paragraphs:["After sufficient parking time, the engine and intake air approach ambient. A coolant reading far away from intake temperature before start points toward sensing/circuit bias.","Record exact values rather than relying on the blue/cold icon or dash needle. Those displays are not calibrated diagnostic instruments."]},{heading:"Highway airflow can expose a thermostat leak",paragraphs:["A thermostat that cannot close may let ECT fall when vehicle speed increases airflow through the radiator. Graph speed and load alongside temperature.","Abort for unstable or rising temperature, low coolant or lost heater output. Those signs require cooling-system safety diagnosis first."]},{heading:"Hybrid warm-up traces need different interpretation",paragraphs:["An Accord Hybrid can stop the gasoline engine while the vehicle remains ready, reducing heat input by design.","Use Honda's hybrid service mode and monitor procedure when required; do not compare its elapsed time directly with a conventional V6."]}],sources:[hondaInfo,hondaManuals]}),

article({slug:"p0301",code:"P0301",title:"P0301 Code Honda Accord: Cylinder 1 Misfire Diagnosis",description:"Diagnose Accord P0301 with a targeted coil/plug/injector/compression workflow, correct cylinder identification and limited 2008–2012 V6 warranty guidance.",definition:"Cylinder 1 Misfire Detected",severity:"Stop soon",driveAdvice:"Stop sustained driving if the MIL flashes, the Accord shakes badly or raw fuel is evident; a single-cylinder misfire can overheat the catalyst quickly. A steady lamp with mild or intermittent symptoms may allow a short diagnostic move, but avoid boost, high rpm and heavy load.",quickAnswer:"P0301 means the PCM attributed enough misfire events to cylinder 1 to mature a fault. It does not identify whether the plug, coil, injector or cylinder sealing failed. First locate cylinder 1 from the exact engine diagram, then save cold/load misfire counts. Inspect that plug in place order, perform one controlled coil swap and see whether the count follows. If it stays on cylinder 1, test injector command/delivery and compression/leak-down rather than swapping more parts. For certain 2008–2012 Accord V6 models, Honda issued P0301–P0304 warranty guidance related to plug fouling/oil consumption. Eligibility and repair require exact VIN/program confirmation and the Honda diagnostic steps; four-cylinder and later turbo P0301 cases are not included.",symptoms:[{key:"flash",label:"MIL flashes continuously",response:"Stop driving and protect the catalyst from raw fuel."},{key:"cold",label:"Cylinder 1 misfires only cold",response:"Capture counts immediately and inspect injector leakage, ignition and sealing cold."},{key:"swap",label:"Misfire follows the coil",response:"Inspect connector/boot and replace the proven failed coil as appropriate."},{key:"oil",label:"V6 plug 1 is oil-fouled",response:"Check oil-consumption history and exact 2008–2012 V6 program eligibility."}],causes:[{cause:"Cylinder 1 spark plug worn, fouled or damaged",evidence:"Abnormal plug condition/gap and ignition evidence",firstTest:"Inspect and compare plugs in cylinder order"},{cause:"Cylinder 1 coil/boot or connector fault",evidence:"Misfire follows controlled coil swap or circuit fails",firstTest:"Targeted swap and loaded circuit test"},{cause:"Injector restriction/leakage or circuit issue",evidence:"Misfire stays at cylinder 1 with delivery/command difference",firstTest:"Injector balance, leak and circuit tests"},{cause:"Compression/valve-clearance/mechanical fault",evidence:"Low relative/measured compression or leak-down",firstTest:"Relative compression then leak-down"},{cause:"Oil-fouling/ring issue in covered V6 population",evidence:"Matched 2008–2012 V6, oil use and Honda diagnosis",firstTest:"Verify 13-078 requirements/status"}],freezeFrame:["Cylinder 1 and all-cylinder misfire counts","RPM, load, coolant temperature and speed","Fuel correction and pressure data","Cylinder 1 plug deposits/gap","Oil consumption and service history","Companion P0300/P0302–P0306, injector and timing codes"],steps:[{title:"Identify cylinder 1 correctly",detail:"Four-cylinder and J-series V6 layouts differ; do not use a generic front-left label."},{title:"Save the condition",detail:"Cold-only and load-only misfire require testing before the symptom disappears."},{title:"Inspect plug and boot",detail:"Keep plugs labeled and compare deposits, gap, cracks, oil and coolant evidence."},{title:"Perform one controlled coil swap",detail:"If the count moves, ignition evidence is strong; if not, return the coil and continue."},{title:"Test injector and circuit",detail:"Compare command, balance and leakage without opening a pressurized direct-injection system unsafely."},{title:"Prove cylinder sealing",detail:"Use relative compression followed by mechanical/leak-down testing."},{title:"Verify original conditions",detail:"Confirm cylinder 1 stays quiet cold and under safe load with no pending P0301."}],dontReplace:"Do not replace every coil for one cylinder code. Do not promise a piston-ring warranty repair from P0301 alone. The Honda V6 program has year/VIN/status and diagnostic requirements, and a cracked plug or injector fault can produce the same cylinder code.",yearNotes:["2008–2012 Accord V6: Honda issued defined P0301–P0304 warranty-extension guidance; verify current VIN eligibility.","Four-cylinder K-series and later 1.5T/2.0T engines are outside that V6 remedy.","Direct-injection fuel pressure is hazardous; use Honda depressurization and test procedures.","Cylinder 1 location must come from the exact engine service diagram before coil/injector work."],faqs:[{question:"Is P0301 always the cylinder 1 coil?",answer:"No. Plug, injector, wiring, compression, valve and mixture faults can all affect cylinder 1."},{question:"Can I drive?",answer:"Not with a flashing MIL or strong shaking; otherwise limit movement to diagnosis."},{question:"Can I swap coils to test?",answer:"Yes when accessible and done carefully, but monitor whether the misfire actually follows."},{question:"What if it stays on cylinder 1?",answer:"Move to plug interpretation, injector delivery/circuit and compression testing."},{question:"Does every 2008–2012 V6 qualify for ring work?",answer:"No. VIN, program status, oil/plug evidence and Honda diagnosis control eligibility."},{question:"Can valve clearance cause P0301?",answer:"Yes. Tight or damaged valves can reduce sealing, often with temperature-dependent symptoms."},{question:"Should I clear the code first?",answer:"No. Save freeze data and counters before changing the evidence."},{question:"What confirms repair?",answer:"No rising cylinder 1 count through the original condition and no pending P0301."}],deepDive:[{heading:"One swap should answer one question",paragraphs:["Move the suspected cylinder 1 coil to a known cylinder, clear only after recording data, and watch enhanced counts under the same condition.","If the misfire remains on cylinder 1, stop moving coils. Repeated swaps add connector damage and do not test fuel or compression."]},{heading:"Read the plug instead of discarding it",paragraphs:["Oil, fuel wetness, coolant-cleaned appearance, cracked porcelain and excessive gap point toward different causes. Compare with a neighboring plug.","Photograph and retain each plug by cylinder until diagnosis is complete. Installing new plugs too early erases evidence and may only delay recurrence."]},{heading:"V6 warranty history is a branch, not the article's answer",paragraphs:["Honda superseded bulletin 10-033 with defined warranty-extension guidance for certain 2008–2012 V6 P0301–P0304 cases.","A matched vehicle still needs the required inspection and current eligibility check. An unmatched engine follows the same targeted ignition, fuel and mechanical workflow as any other P0301."]}],sources:[misfireV6,hondaInfo,hondaManuals]}),
];
